#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

REPO="MatthewAaronGarza/claude-warmup"
DISPATCH_URL="https://api.github.com/repos/${REPO}/actions/workflows/warmup.yml/dispatches"

# Where the token is remembered between runs. Gitignored.
ENV_FILE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/.env"

# dispatch TOKEN — fire the workflow through GitHub's API. Prints the HTTP status.
dispatch() {
  curl -s -o /dev/null -w '%{http_code}' -X POST "$DISPATCH_URL" \
    -H "Authorization: Bearer $1" \
    -H "Accept: application/vnd.github+json" \
    -H "X-GitHub-Api-Version: 2022-11-28" \
    -d '{"ref":"main"}'
}

# latest_run_id — id of the newest warmup run, or empty.
latest_run_id() {
  gh run list --repo "$REPO" --workflow=warmup.yml --limit 1 --json databaseId \
    --jq '.[0].databaseId' 2>/dev/null || true
}

# wait_for_dispatch BEFORE_ID — poll up to 90s for a workflow_dispatch run newer than BEFORE_ID.
wait_for_dispatch() {
  local before="$1" i id ev
  for i in $(seq 1 18); do
    id=$(latest_run_id)
    if [[ -n "$id" && "$id" != "$before" ]]; then
      ev=$(gh run list --repo "$REPO" --workflow=warmup.yml --limit 1 --json event --jq '.[0].event' 2>/dev/null || true)
      if [[ "$ev" == "workflow_dispatch" ]]; then
        printf '  %s✓ GitHub started run %s%s (event: workflow_dispatch)\n' "$GREEN" "$id" "$RESET"
        return 0
      fi
    fi
    sleep 5
  done
  return 1
}

banner "claude-warmup: reliable triggering via cron-job.org"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "GitHub: create a fine-grained token"
say "cron-job.org needs a token that can do exactly one thing: start the"
say "warmup workflow in ${REPO}. A fine-grained token scoped to"
say "that one repo is the safest kind."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: claude-warmup dispatcher"
step "Expiration: pick 'Custom' and set it about a year out (GitHub emails you before it expires)."
step "Repository access: 'Only select repositories' -> choose claude-warmup."
step "Permissions -> Repository permissions -> Actions: 'Read and write'."
note "(Metadata: Read-only is added automatically. Nothing else is needed.)"
step "Click 'Generate token' at the bottom, then copy the token (starts with github_pat_)."
ask_secret GITHUB_DISPATCH_TOKEN "Paste the token:"
if [[ -z "${GITHUB_DISPATCH_TOKEN}" ]]; then
  warn "No token entered. Re-run this wizard when you have one."
  exit 1
fi
write_env GITHUB_DISPATCH_TOKEN "$GITHUB_DISPATCH_TOKEN"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Verify the token by firing the workflow once"
say "This sends the same request cron-job.org will send. The workflow's time"
say "gate decides whether to actually ping Claude, so this is safe at any hour."
before=$(latest_run_id)
code=$(dispatch "$GITHUB_DISPATCH_TOKEN")
if [[ "$code" == "204" ]]; then
  printf '  %s✓ GitHub accepted the dispatch (HTTP 204)%s\n' "$GREEN" "$RESET"
else
  warn "GitHub answered HTTP $code instead of 204."
  say "401 = token wrong or expired. 403/404 = token lacks Actions: Read and write on claude-warmup."
  say "Fix the token in GitHub, then re-run this wizard."
  exit 1
fi
say "Waiting for GitHub to start the run..."
if ! wait_for_dispatch "$before"; then
  warn "Dispatch was accepted but no run appeared within 90s. Check:"
  say "https://github.com/${REPO}/actions"
  pause "Press Enter to continue anyway"
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "cron-job.org: sign in or create a free account"
say "cron-job.org is a free scheduler that calls a web address on a timer,"
say "to the minute, and emails you when a call fails."
open_url "https://console.cron-job.org/signup"
step "Create an account (or sign in if you already have one)."
step "Confirm the email they send, then come back here."
pause "Signed in? Press Enter."

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "cron-job.org: create the job"
say "The authorization header is copied to your clipboard for step 6."
if command -v clip.exe >/dev/null 2>&1; then
  printf '%s' "Bearer ${GITHUB_DISPATCH_TOKEN}" | clip.exe
  printf '  %s✓ copied%s \"Bearer github_pat_...\" to the clipboard\n' "$GREEN" "$RESET"
else
  warn "No clipboard tool found. The header value is:"
  say "Bearer ${GITHUB_DISPATCH_TOKEN}"
fi
open_url "https://console.cron-job.org/jobs/create"
note "Labels below match the cron-job.org console as of Sep 2026 and may differ slightly."
step "1. Title: claude-warmup"
step "2. URL:  ${DISPATCH_URL}"
step "3. Execution schedule: choose 'Custom'. Timezone: America/New_York."
step "   Days of month: every. Days of week: every. Months: every."
step "   Hours: tick 6 through 20 (6am to 8pm). Minutes: tick only 17."
note "   Picking the timezone here means daylight saving is handled for you."
step "4. Open the 'Advanced' tab. Request method: POST."
step "5. Request body:  {\"ref\":\"main\"}"
step "6. Headers, add three (Key = Value):"
say  "     Authorization        = <paste from clipboard>"
say  "     Accept               = application/vnd.github+json"
say  "     X-GitHub-Api-Version = 2022-11-28"
step "7. Turn on 'Save responses in job history' (useful when debugging)."
step "8. Open the 'Notifications' tab and turn on notify on failure."
step "9. Click 'Create'."
pause "Job created? Press Enter."

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "cron-job.org: test run, confirmed by GitHub"
say "On the job's page there is a 'Test run' (or 'Run now') button."
before=$(latest_run_id)
step "Click it. cron-job.org shows the HTTP status it got back; 204 is correct."
say "Waiting up to 90s for GitHub to report the run..."
if wait_for_dispatch "$before"; then
  say "cron-job.org can start the workflow. From now on it fires at :17, 6am-8pm Eastern."
else
  warn "No new run seen. If cron-job.org shows anything other than 204, re-check"
  say "the URL, the POST method, the request body, and the three headers."
  SKIPPED+=("cron-job.org test run did not reach GitHub; re-check the job settings")
fi

finish
say "Next: tomorrow after 6:30am Eastern, open https://github.com/${REPO}/actions"
say "and check for a workflow_dispatch run around 6:17am."
